import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Search, Star, X, MessageSquare } from 'lucide-react';
import toast from 'react-hot-toast';
import AdminReviewModerationCard from '../components/AdminReviewModerationCard';

const mockReviews = [
  { id: 1, user: { name: 'Arjun Sharma', email: 'arjun@email.com' }, package: 'Golden Triangle Tour', rating: 5, title: 'Absolutely amazing experience!', comment: 'The tour was incredibly well organized. Our guide Raj was knowledgeable, friendly, and made the entire trip memorable. The hotels were excellent and food was delicious. Highly recommend this package to anyone visiting Rajasthan!', date: '2026-04-10', status: 'pending', images: [] },
  { id: 2, user: { name: 'Priya Patel', email: 'priya@email.com' }, package: 'Kerala Backwaters', rating: 4, title: 'Beautiful but could be better', comment: 'The backwaters are stunning. Loved the houseboat experience. The only downside was the food on day 2 was not up to the mark. Otherwise a wonderful trip!', date: '2026-04-09', status: 'approved', images: [] },
  { id: 3, user: { name: 'Rahul Gupta', email: 'rahul@email.com' }, package: 'Goa Beach Holiday', rating: 2, title: 'Disappointing experience', comment: 'The accommodation was not as shown in the pictures. Room was smaller and the beach was 20 minutes away despite being advertised as beachfront. Very misleading. Will not book again.', date: '2026-04-08', status: 'flagged', images: [] },
  { id: 4, user: { name: 'Ananya Singh', email: 'ananya@email.com' }, package: 'Manali Snow Trek', rating: 5, title: 'Life changing trek!', comment: 'This was my first trekking experience and it was beyond perfect. The team was professional, safety was prioritized, and the views were breathtaking. Already planning my next trek with them!', date: '2026-04-07', status: 'approved', images: [] },
  { id: 5, user: { name: 'Vikram Reddy', email: 'vikram@email.com' }, package: 'Andaman Explorer', rating: 3, title: 'Average experience', comment: 'The snorkeling was great but the island hopping felt rushed. More time at Havelock would have been better. The hotel was nice though. Overall decent trip for the price.', date: '2026-04-06', status: 'pending', images: [] },
  { id: 6, user: { name: 'Kavya Nair', email: 'kavya@email.com' }, package: 'Rajasthan Heritage', rating: 1, title: 'Worst experience', comment: 'Completely fraud company. Took advance payment and changed hotels at last minute. Guide was not available. Would not recommend to anyone.', date: '2026-04-05', status: 'rejected', images: [] },
];

const FILTERS = [
  { label: 'All', value: 'all' },
  { label: 'Pending', value: 'pending' },
  { label: 'Approved', value: 'approved' },
  { label: 'Rejected', value: 'rejected' },
  { label: 'Flagged', value: 'flagged' },
];

const AdminReviewModerationPage = () => {
  const [reviews, setReviews] = useState(mockReviews);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [selectedReview, setSelectedReview] = useState(null);

  const filtered = useMemo(() => {
    return reviews.filter((r) => {
      const matchSearch = r.user.name.toLowerCase().includes(search.toLowerCase()) ||
        r.package.toLowerCase().includes(search.toLowerCase()) ||
        r.comment.toLowerCase().includes(search.toLowerCase());
      const matchStatus = statusFilter === 'all' || r.status === statusFilter;
      return matchSearch && matchStatus;
    });
  }, [reviews, search, statusFilter]);

  const handleApprove = (id) => {
    setReviews((prev) => prev.map((r) => r.id === id ? { ...r, status: 'approved' } : r));
    toast.success('Review approved and published');
  };

  const handleReject = (id) => {
    setReviews((prev) => prev.map((r) => r.id === id ? { ...r, status: 'rejected' } : r));
    toast.success('Review rejected');
  };

  const pendingCount = reviews.filter((r) => r.status === 'pending').length;
  const avgRating = (reviews.reduce((s, r) => s + r.rating, 0) / reviews.length).toFixed(1);

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 lg:p-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Review Moderation</h1>
          <p className="text-sm text-gray-500">{pendingCount} reviews pending approval</p>
        </div>
        <div className="flex items-center gap-2 px-4 py-2 bg-amber-50 border border-amber-200 rounded-xl">
          <Star className="w-4 h-4 text-amber-400 fill-amber-400" />
          <span className="text-sm font-bold text-amber-700">{avgRating}</span>
          <span className="text-xs text-amber-600">avg rating</span>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-5">
        {FILTERS.filter((f) => f.value !== 'all').map(({ label, value }) => {
          const count = reviews.filter((r) => r.status === value).length;
          const colors = { pending: 'text-amber-600', approved: 'text-emerald-600', rejected: 'text-red-500', flagged: 'text-orange-600' };
          return (
            <div key={value} className="bg-white rounded-xl border border-gray-100 shadow-sm p-4">
              <p className={`text-xl font-bold ${colors[value]}`}>{count}</p>
              <p className="text-xs text-gray-500">{label}</p>
            </div>
          );
        })}
      </div>

      {/* Filters */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-5">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search reviews..." className="w-full pl-9 pr-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0B4F6C]/30 focus:border-[#0B4F6C]" />
          </div>
          <div className="flex gap-1 flex-wrap">
            {FILTERS.map(({ label, value }) => (
              <button key={value} onClick={() => setStatusFilter(value)} className={`px-3 py-2 text-xs font-medium rounded-lg transition-all ${statusFilter === value ? 'bg-[#0B4F6C] text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}>
                {label} {value !== 'all' && `(${reviews.filter((r) => r.status === value).length})`}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Review Cards */}
      {filtered.length === 0 ? (
        <div className="py-16 text-center bg-white rounded-xl border border-gray-100">
          <MessageSquare className="w-12 h-12 text-gray-300 mx-auto mb-3" />
          <p className="text-gray-500 font-medium">No reviews found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          <AnimatePresence>
            {filtered.map((review) => (
              <AdminReviewModerationCard
                key={review.id}
                review={review}
                onApprove={handleApprove}
                onReject={handleReject}
                onView={setSelectedReview}
              />
            ))}
          </AnimatePresence>
        </div>
      )}

      {/* Full Review Modal */}
      <AnimatePresence>
        {selectedReview && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <motion.div initial={{ scale: 0.95, y: 20 }} animate={{ scale: 1, y: 0 }} exit={{ scale: 0.95 }} className="bg-white rounded-2xl shadow-2xl w-full max-w-lg">
              <div className="flex items-center justify-between p-5 border-b border-gray-100">
                <h3 className="text-lg font-bold text-gray-900">Review Details</h3>
                <button onClick={() => setSelectedReview(null)} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
              </div>
              <div className="p-5 space-y-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-[#0B4F6C] to-[#00B4D8] flex items-center justify-center text-white font-bold">{selectedReview.user.name.charAt(0)}</div>
                  <div>
                    <p className="font-semibold text-gray-800">{selectedReview.user.name}</p>
                    <p className="text-xs text-gray-500">{selectedReview.user.email}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  {[...Array(5)].map((_, i) => (
                    <Star key={i} className={`w-5 h-5 ${i < selectedReview.rating ? 'text-amber-400 fill-amber-400' : 'text-gray-200 fill-gray-200'}`} />
                  ))}
                  <span className="text-sm font-bold text-gray-700">{selectedReview.rating}/5</span>
                </div>
                <p className="text-sm font-semibold text-[#0B4F6C] bg-[#0B4F6C]/10 px-2 py-1 rounded-lg inline-block">{selectedReview.package}</p>
                {selectedReview.title && <h4 className="text-base font-bold text-gray-900">"{selectedReview.title}"</h4>}
                <p className="text-sm text-gray-700 leading-relaxed">{selectedReview.comment}</p>
                <p className="text-xs text-gray-400">{new Date(selectedReview.date).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                {selectedReview.status === 'pending' && (
                  <div className="flex gap-3 pt-2">
                    <button onClick={() => { handleApprove(selectedReview.id); setSelectedReview(null); }} className="flex-1 py-2.5 bg-emerald-600 text-white text-sm font-semibold rounded-lg hover:bg-emerald-700">Approve</button>
                    <button onClick={() => { handleReject(selectedReview.id); setSelectedReview(null); }} className="flex-1 py-2.5 bg-red-500 text-white text-sm font-semibold rounded-lg hover:bg-red-600">Reject</button>
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminReviewModerationPage;
